import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"TextInput","description":"","frontmatter":{},"headers":[],"relativePath":"components/text-input.md","filePath":"components/text-input.md"}'),n={name:"components/text-input.md"};function r(i,t,c,s,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="textinput" tabindex="-1">TextInput <a class="header-anchor" href="#textinput" aria-label="Permalink to &quot;TextInput&quot;">​</a></h1><p>TextInput is the input of one line of text.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for one line of text, in a <a href="./field">Field</a>, which gives it a name, or named with <code>aria-label</code>. <code>unit</code> places a unit inside on the right, <code>mono</code> sets a code or an identifier in the monospace font, and <code>title</code> makes it the input of a name, at the size of h2. <code>suggestions</code> lists values that may be picked or typed over. For several lines use a <a href="./textarea">Textarea</a>, for a number a <a href="./number-input">NumberInput</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>&#39;&#39;</code></td><td>The text (bindable)</td></tr><tr><td><code>type</code></td><td><code>text</code></td><td><code>text</code>, <code>email</code>, <code>password</code> or <code>url</code></td></tr><tr><td><code>placeholder</code></td><td></td><td>Shown while it is empty</td></tr><tr><td><code>id</code>, <code>name</code>, <code>autocomplete</code></td><td></td><td>Passed to the input</td></tr><tr><td><code>unit</code></td><td></td><td>A unit on the right inside the control</td></tr><tr><td><code>mono</code></td><td><code>false</code></td><td>The monospace font, with figures of equal width</td></tr><tr><td><code>title</code></td><td><code>false</code></td><td>The size and weight of h2</td></tr><tr><td><code>suggestions</code></td><td></td><td>Values to pick from, or to type over</td></tr><tr><td><code>error</code></td><td><code>false</code></td><td>The line turns red</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Cannot be focused or changed</td></tr><tr><td><code>readonly</code></td><td><code>false</code></td><td>Can be focused and selected, not changed</td></tr><tr><td><code>oninput</code>, <code>onchange</code></td><td></td><td>Every key stroke, and the committed value</td></tr><tr><td><code>onkeydown</code>, <code>onblur</code></td><td></td><td>Passed to the input</td></tr></tbody></table><p>Other attributes (<code>aria-*</code>, <code>inputmode</code>, <code>maxlength</code>) go to the input.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The control is a <code>&lt;label&gt;</code> of the height its container declares, a button&#39;s by default, with one line in line-strong and pad-md at the sides; a press anywhere on it focuses the input. The input inside has no line and no ring of its own. Focus turns the control&#39;s line blue-ink, an error turns it red-ink, and the placeholder is faint. The unit is muted and trimmed to its ink. The width is the container&#39;s. Disabled is dimmed.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/text-input/" title="TextInput" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/text-input/" target="_blank" rel="noopener">TextInput</a></figcaption></figure>',11)])])}const m=e(n,[["render",r]]);export{u as __pageData,m as default};
